    {
      "name": "incident_action_type",
      "analytical_usefulness": 0.7,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Break_fix vs installation/update gives a useful axis to distinguish reactive hardware failures from requests. Mostly grounded, though 'Issue installing new software' labeled break_fix is a slightly loose reading."
    },
    {
      "name": "affected_system_scope",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.75,
      "hallucination_observed": false,
      "rationale": "Scope (single_device, peripheral, server_infra) helps characterize hardware impact. Groundedness is moderate; scope is often inferred from category rather than explicit in terse descriptions, but inferences are plausible."
    },
    {
      "name": "incident_volume_burst",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.6,
      "hallucination_observed": false,
      "rationale": "A volume-burst flag is directly relevant to an 'anomaly window' query. However it cannot be derived from a single row's text; it requires aggregating timestamps, so per-row groundedness is uncertain and only weakly evidenced."
    },
    {
      "name": "recurrence_signal",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.55,
      "hallucination_observed": false,
      "rationale": "Recurrence is a meaningful anomaly signal, but not derivable from a single short_description; it depends on cross-row analysis not visible in samples, lowering groundedness confidence."
    },
    {
      "name": "software_trigger_present",
      "analytical_usefulness": 0.6,
      "source_groundedness": 0.7,
      "hallucination_observed": false,
      "rationale": "Whether a software trigger accompanies an incident is somewhat useful for isolating hardware vs software causes, though it partly restates incident_category. Samples are consistent with text."
    },
    {
      "name": "caller_repeat_reporter",
      "analytical_usefulness": 0.65,
      "source_groundedness": 0.5,
      "hallucination_observed": false,
      "rationale": "A repeat-reporter flag could add a behavioral signal, but it is near-constant (505 true / 95 false) and derives from caller_id aggregation not shown in row text; the overwhelmingly 'true' distribution and non-obvious derivation reduce both usefulness and groundedness confidence."
    }
  ],
  "analytical_usefulness": 0.78,
  "source_groundedness": 0.72,
  "rationale": "Most added columns give genuine analytical axes for identifying hardware incidents and anomaly-window signals (category, symptom, scope, burst, recurrence). Text-derivable categorical columns are well grounded in the samples. The aggregate/behavioral flags (volume_burst, recurrence, repeat_reporter) are query-relevant but rely on cross-row computation not evidenced in single-row source text, and caller_repeat_reporter is near-constant, modestly lowering the holistic scores. No outright hallucinations observed."
